let inc_art = std::path::Path::new("/Users/kevintruong/project/SpurCode/docs/research/artifacts/2026-11-15-duckdb-incremental-children");
let inc_log = std::fs::File::create(inc_art.join("matched-r0-process.log"))?;
let inc_stderr = inc_log.try_clone()?;
let inc_status = std::process::Command::new("/private/tmp/spur-graph-duckdb-v2-20261114/bin/python")
    .arg(inc_art.join("benchmark.py"))
    .arg("--candidate-sql").arg(inc_art.join("approved-candidate.sql"))
    .args(["--name", "matched-r0"])
    .stdout(std::process::Stdio::from(inc_log))
    .stderr(std::process::Stdio::from(inc_stderr))
    .status()?;
assert!(inc_status.success(), "Benchmark failed; inspect matched-r0-process.log");
let inc_result: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(inc_art.join("matched-r0/result.json"))?)?;
assert_eq!(inc_result["status"], "passed");
println!("Matched old/new workflow benchmark: {}", inc_result["status"]);
println!("Warm observations and medians: {}", inc_result["warm"]);
println!("Typed Parquet checks without extension: {}", inc_result["typed_parquet_without_extension"]);
println!("Exact final old/new differences: {}", inc_result["old_new_exact"]);
